def solve(amount):
    class Client:
        def charge(self, minor):
            return f"ok:{minor}"

    class Checkout:
        def __init__(self, client):
            self.client = client

        def place(self, minor):
            if type(minor) is not int or minor <= 0:
                return "error"
            return self.client.charge(minor)

    return Checkout(Client()).place(amount)
